preConditionHook:
// Lowest(l, lookback)[1] / Highest(h, lookback)[1]: bars 1 .. lookback.
// EL's Extremes() seeds at the first bar of the window and scans the rest
// with a strict, tolerance-carrying comparison (see CloseAbovePriorHighestHigh).
priorLow = low[1];
priorHigh = high[1];
for (int i = 2; i <= (int)lookback; ++i) {
    if (el_lt(low[i], priorLow)) priorLow = low[i];
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
}
